using System;using System.IO;using System.Linq;using System.Collections.Generic;using UnityEngine;using UnityEditor;
public static class NurseFaceTopology {
 public const string Prefix="BeforeFaceSculptV3_";
 static BoneWeight Mix(BoneWeight a,BoneWeight b){var values=new Dictionary<int,float>();foreach(var w in new[]{a,b}){int[] ids={w.boneIndex0,w.boneIndex1,w.boneIndex2,w.boneIndex3};float[] weights={w.weight0,w.weight1,w.weight2,w.weight3};for(int k=0;k<4;k++){if(!values.ContainsKey(ids[k]))values[ids[k]]=0;values[ids[k]]+=weights[k]*.5f;}}var top=values.OrderByDescending(p=>p.Value).Take(4).ToArray();float sum=top.Sum(p=>p.Value);return new BoneWeight{boneIndex0=top[0].Key,weight0=top[0].Value/sum,boneIndex1=top.Length>1?top[1].Key:0,weight1=top.Length>1?top[1].Value/sum:0,boneIndex2=top.Length>2?top[2].Key:0,weight2=top.Length>2?top[2].Value/sum:0,boneIndex3=top.Length>3?top[3].Key:0,weight3=top.Length>3?top[3].Value/sum:0};}
 public static Mesh Baseline(SkinnedMeshRenderer renderer){string path=NurseVisualOptimization.Folder+"/"+Prefix+renderer.name+".asset";var asset=AssetDatabase.LoadAssetAtPath<Mesh>(path);if(asset!=null)return asset;var source=AssetDatabase.LoadAssetAtPath<Mesh>(NurseVisualOptimization.Folder+"/BeforeFaceSculptV1_"+renderer.name+".asset");if(source==null)throw new Exception("Missing independent Nurse source baseline");
  if(renderer.name=="LOD2"){AssetDatabase.CopyAsset(AssetDatabase.GetAssetPath(source),path);return AssetDatabase.LoadAssetAtPath<Mesh>(path);}
  var v=source.vertices.ToList();var n=source.normals.ToList();var t=source.tangents.ToList();var uv=source.uv.ToList();var w=source.boneWeights.ToList();var edges=new Dictionary<string,int>();var split=new HashSet<string>();var submeshes=new List<int[]>();
  var current=renderer.sharedMesh;renderer.sharedMesh=source;var posed=NurseAnatomyRender.WorldSkin(renderer);renderer.sharedMesh=current;var world=posed.vertices.ToList();var worldNormals=posed.normals.ToList();var worldTangents=posed.tangents.ToList();UnityEngine.Object.DestroyImmediate(posed);var matrices=renderer.bones.Select((bone,i)=>bone.localToWorldMatrix*source.bindposes[i]).ToArray();float maxError=0,maxBindDifference=0;
  for(int i=0;i<v.Count;i++)if(world[i].y>1.5f)maxBindDifference=Mathf.Max(maxBindDifference,Vector3.Distance(world[i],renderer.transform.TransformPoint(v[i])));
  Func<BoneWeight,Matrix4x4> skinFor=bw=>{int[] ids={bw.boneIndex0,bw.boneIndex1,bw.boneIndex2,bw.boneIndex3};float[] values={bw.weight0,bw.weight1,bw.weight2,bw.weight3};var matrix=Matrix4x4.zero;for(int k=0;k<4;k++)for(int a=0;a<4;a++)for(int b=0;b<4;b++)matrix[a,b]+=matrices[ids[k]][a,b]*values[k];return matrix;};
  Func<int,string> pointKey=i=>Mathf.RoundToInt(world[i].x*100000)+","+Mathf.RoundToInt(world[i].y*100000)+","+Mathf.RoundToInt(world[i].z*100000);
  Func<int,int,string> key=(a,b)=>{string ka=pointKey(a),kb=pointKey(b);return String.CompareOrdinal(ka,kb)<0?ka+":"+kb:kb+":"+ka;};Action<int,int> mark=(a,b)=>split.Add(key(a,b));
  Func<Vector3,Vector3,Vector4,Vector2,BoneWeight,int> add=(position,normal,tangent,coord,bw)=>{int id=v.Count;var skin=skinFor(bw);var local=skin.inverse.MultiplyPoint3x4(position);maxError=Mathf.Max(maxError,Vector3.Distance(skin.MultiplyPoint3x4(local),position));v.Add(local);n.Add(skin.inverse.MultiplyVector(normal).normalized);var xyz=skin.inverse.MultiplyVector(new Vector3(tangent.x,tangent.y,tangent.z)).normalized;t.Add(new Vector4(xyz.x,xyz.y,xyz.z,tangent.w));uv.Add(coord);w.Add(bw);world.Add(position);worldNormals.Add(normal);worldTangents.Add(tangent);return id;};
  for(int slot=0;slot<source.subMeshCount;slot++){var indices=source.GetTriangles(slot);for(int i=0;i<indices.Length;i+=3){var p=(world[indices[i]]+world[indices[i+1]]+world[indices[i+2]])/3;if(slot==0&&p.y>1.515f&&p.y<1.705f&&Mathf.Abs(p.x)<.080f&&p.z>.035f){mark(indices[i],indices[i+1]);mark(indices[i+1],indices[i+2]);mark(indices[i+2],indices[i]);}}}
  Func<int,int,int> mid=(a,b)=>{string k=Mathf.Min(a,b)+":"+Mathf.Max(a,b);int id;if(edges.TryGetValue(k,out id))return id;id=add((world[a]+world[b])*.5f,(worldNormals[a]+worldNormals[b]).normalized,worldTangents[a],(uv[a]+uv[b])*.5f,Mix(w[a],w[b]));edges[k]=id;return id;};
  // Marked edges are split on both adjacent triangles, including transition triangles, to avoid T-junctions.
  for(int slot=0;slot<source.subMeshCount;slot++){var output=new List<int>();var indices=source.GetTriangles(slot);for(int i=0;i<indices.Length;i+=3){int a=indices[i],b=indices[i+1],c=indices[i+2];bool ab=split.Contains(key(a,b)),bc=split.Contains(key(b,c)),ca=split.Contains(key(c,a));int count=(ab?1:0)+(bc?1:0)+(ca?1:0);if(count==0){output.AddRange(new[]{a,b,c});continue;}if(count==3){int d=mid(a,b),e=mid(b,c),f=mid(c,a);output.AddRange(new[]{a,d,f,d,b,e,f,e,c,d,e,f});continue;}var polygon=new List<int>{a};if(ab)polygon.Add(mid(a,b));polygon.Add(b);if(bc)polygon.Add(mid(b,c));polygon.Add(c);if(ca)polygon.Add(mid(c,a));
   int centre=add((world[a]+world[b]+world[c])/3,(worldNormals[a]+worldNormals[b]+worldNormals[c]).normalized,worldTangents[a],(uv[a]+uv[b]+uv[c])/3,Mix(Mix(w[a],w[b]),w[c]));for(int j=0;j<polygon.Count;j++)output.AddRange(new[]{centre,polygon[j],polygon[(j+1)%polygon.Count]});}
   submeshes.Add(output.ToArray());}
  var result=new Mesh{name=source.name+"_FaceTopology",indexFormat=UnityEngine.Rendering.IndexFormat.UInt32};result.vertices=v.ToArray();result.normals=n.ToArray();result.tangents=t.ToArray();result.uv=uv.ToArray();result.boneWeights=w.ToArray();result.bindposes=source.bindposes;result.subMeshCount=submeshes.Count;for(int i=0;i<submeshes.Count;i++)result.SetTriangles(submeshes[i],i);result.RecalculateBounds();if(maxError>.00001f)throw new Exception("Facial subdivision bind reconstruction mismatch");AssetDatabase.CreateAsset(result,path);File.AppendAllText(NurseVisualOptimization.Out+"/face-topology-bind-proof.txt",renderer.name+": new vertex bind reconstruction max error="+maxError+"m; existing head bind/posed difference="+maxBindDifference+"m; vertices="+v.Count+" triangles="+result.triangles.Length/3+"; split edges propagated across coincident UV seam endpoints.\n");return result;
 }
 public static void CloseEditedForehead(Vector3[] vertices,Mesh source,SkinnedMeshRenderer renderer){
  var original=source.vertices;var weights=source.boneWeights;var matrices=renderer.bones.Select((b,i)=>b.localToWorldMatrix*source.bindposes[i]).ToArray();var originalWorld=new Vector3[vertices.Length];var currentWorld=new Vector3[vertices.Length];var skins=new Matrix4x4[vertices.Length];var candidates=new List<int>();
  for(int i=0;i<vertices.Length;i++){var w=weights[i];int[] ids={w.boneIndex0,w.boneIndex1,w.boneIndex2,w.boneIndex3};float[] amounts={w.weight0,w.weight1,w.weight2,w.weight3};var skin=Matrix4x4.zero;for(int k=0;k<4;k++)for(int a=0;a<4;a++)for(int b=0;b<4;b++)skin[a,b]+=matrices[ids[k]][a,b]*amounts[k];skins[i]=skin;originalWorld[i]=skin.MultiplyPoint3x4(original[i]);currentWorld[i]=skin.MultiplyPoint3x4(vertices[i]);var p=originalWorld[i];if(p.y>1.655f&&p.y<1.740f&&Mathf.Abs(p.x)<.10f&&p.z>.010f)candidates.Add(i);}
  var parent=Enumerable.Range(0,vertices.Length).ToArray();Func<int,int> root=null;root=i=>parent[i]==i?i:parent[i]=root(parent[i]);float epsilon=.00002f;
  for(int a=0;a<candidates.Count;a++)for(int b=a+1;b<candidates.Count;b++){int i=candidates[a],j=candidates[b];if((original[i]-original[j]).sqrMagnitude<epsilon*epsilon)parent[root(j)]=root(i);}
  int groups=0;foreach(var group in candidates.GroupBy(i=>root(i))){if(group.Count()<2||!group.Any(i=>(originalWorld[i]-currentWorld[i]).sqrMagnitude>1e-12f))continue;var average=Vector3.zero;foreach(int i in group)average+=currentWorld[i];average/=group.Count();foreach(int i in group)vertices[i]=skins[i].inverse.MultiplyPoint3x4(average);groups++;}
  File.AppendAllText(NurseVisualOptimization.Out+"/forehead-seam-repair.txt",renderer.name+": edited coincident forehead seam groups closed="+groups+"; source bind-space tolerance 0.02 mm; distinct neighboring topology is not collapsed.\n");
 }
}
